package com.coraline.postgame;

import java.nio.file.*;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.LevelResource;

/** Finite raid admission. Unknown data freezes issuance, never resets a clock. */
final class BreachRaidData extends SavedData {
    final UUID generation;private CompoundTag raw;private String problem="";
    private BreachRaidData(UUID id){generation=id;raw=new CompoundTag();raw.putInt("Version",1);raw.putUUID("Generation",id);raw.putLong("NextGlobal",0);raw.put("Players",new CompoundTag());raw.put("Raids",new CompoundTag());}
    private BreachRaidData(UUID id,CompoundTag n){generation=id;raw=n.copy();try{if(!n.contains("Version",Tag.TAG_INT)||n.getInt("Version")!=1||!n.hasUUID("Generation")||!id.equals(n.getUUID("Generation"))||!n.contains("NextGlobal",Tag.TAG_LONG)||n.getLong("NextGlobal")<0||!n.contains("Players",Tag.TAG_COMPOUND)||!n.contains("Raids",Tag.TAG_COMPOUND)||n.getCompound("Players").size()>4096||n.getCompound("Raids").size()>64)throw new IllegalArgumentException("Invalid raid journal");for(String key:n.getCompound("Players").getAllKeys())if(!UUID.fromString(key).toString().equals(key)||!n.getCompound("Players").contains(key,Tag.TAG_LONG)||n.getCompound("Players").getLong(key)<0)throw new IllegalArgumentException("Invalid raid cooldown");var members=new HashSet<UUID>();for(String key:n.getCompound("Raids").getAllKeys()){if(!UUID.fromString(key).toString().equals(key)||!n.getCompound("Raids").contains(key,Tag.TAG_COMPOUND))throw new IllegalArgumentException("Invalid raid ID");var row=n.getCompound("Raids").getCompound(key);if(!row.hasUUID("Owner")||!row.contains("Born",Tag.TAG_LONG)||row.getLong("Born")<0||!row.contains("Done",Tag.TAG_BYTE)||row.getByte("Done")<0||row.getByte("Done")>1||!row.contains("Members",Tag.TAG_LIST))throw new IllegalArgumentException("Invalid raid");if(row.contains("Colony")&&!row.hasUUID("Colony"))throw new IllegalArgumentException("Invalid reinforcement source");var list=row.getList("Members",Tag.TAG_COMPOUND);if(list.size()!=((ListTag)row.get("Members")).size()||list.isEmpty()||list.size()>8)throw new IllegalArgumentException("Invalid raid size");for(var entry:list){var member=(CompoundTag)entry;if(!member.hasUUID("Entity")||!members.add(member.getUUID("Entity"))||!member.contains("Dead",Tag.TAG_BYTE)||member.getByte("Dead")<0||member.getByte("Dead")>1)throw new IllegalArgumentException("Ambiguous raid actor");}}}catch(IllegalArgumentException malformed){problem=malformed.getMessage();}}
    private static String name(UUID id){return "coraline_breach_raids_"+id;}
    static BreachRaidData get(MinecraftServer server,UUID id){var path=server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(id)+".dat");return server.overworld().getDataStorage().computeIfAbsent(n->new BreachRaidData(id,n),()->Files.notExists(path,LinkOption.NOFOLLOW_LINKS)?new BreachRaidData(id):new BreachRaidData(id,new CompoundTag()),name(id));}
    boolean ready(UUID owner,long now){if(!problem.isEmpty()||now<raw.getLong("NextGlobal")||now<raw.getCompound("Players").getLong(owner.toString())||!raw.getCompound("Players").contains(owner.toString())&&raw.getCompound("Players").size()>=4096)return false;int active=0;for(String key:raw.getCompound("Raids").getAllKeys())if(!raw.getCompound("Raids").getCompound(key).getBoolean("Done"))active++;return active<2;}
    CompoundTag raid(UUID id){return problem.isEmpty()&&raw.getCompound("Raids").contains(id.toString(),Tag.TAG_COMPOUND)?raw.getCompound("Raids").getCompound(id.toString()):null;}
    Optional<UUID> colony(UUID raid){var row=raid(raid);return row!=null&&row.hasUUID("Colony")?Optional.of(row.getUUID("Colony")):Optional.empty();}
    boolean member(UUID raid,UUID actor){var row=raid(raid);return row!=null&&!row.getBoolean("Done")&&row.getList("Members",Tag.TAG_COMPOUND).stream().anyMatch(n->((CompoundTag)n).getUUID("Entity").equals(actor)&&!((CompoundTag)n).getBoolean("Dead"));}
    void killed(UUID raid,UUID actor){var row=raid(raid);if(row==null||row.getBoolean("Done"))return;for(var entry:row.getList("Members",Tag.TAG_COMPOUND)){var n=(CompoundTag)entry;if(n.getUUID("Entity").equals(actor))n.putBoolean("Dead",true);}if(row.getList("Members",Tag.TAG_COMPOUND).stream().allMatch(n->((CompoundTag)n).getBoolean("Dead")))row.putBoolean("Done",true);setDirty();}
    boolean admit(MinecraftServer server,UUID raid,UUID owner,List<? extends net.minecraft.world.entity.Mob> actors,long now){return admit(server,raid,owner,actors,now,null,1200);}
    boolean admit(MinecraftServer server,UUID raid,UUID owner,List<? extends net.minecraft.world.entity.Mob> actors,long now,UUID colony,int interval){if(interval!=600&&interval!=1200)return false;if(!ready(owner,now)||actors.isEmpty()||actors.size()>8||raw.getCompound("Raids").contains(raid.toString()))return false;var rows=raw.getCompound("Raids");if(rows.size()>=64){String oldest=null;long born=Long.MAX_VALUE;for(String key:rows.getAllKeys()){var row=rows.getCompound(key);if(row.getBoolean("Done")&&row.getLong("Born")<born){oldest=key;born=row.getLong("Born");}}if(oldest==null)return false;rows.remove(oldest);}var row=new CompoundTag();row.putUUID("Owner",owner);if(colony!=null)row.putUUID("Colony",colony);row.putLong("Born",now);row.putBoolean("Done",false);var list=new ListTag();for(var actor:actors){var n=new CompoundTag();n.putUUID("Entity",actor.getUUID());n.putBoolean("Dead",false);list.add(n);}row.put("Members",list);rows.put(raid.toString(),row);raw.getCompound("Players").putLong(owner.toString(),now+24000);raw.putLong("NextGlobal",now+interval);return checkpoint(server);}
    void finish(UUID raid){var row=raid(raid);if(row!=null){row.putBoolean("Done",true);setDirty();}}
    void reconcile(long now,boolean retreat){if(!problem.isEmpty())return;for(String key:raw.getCompound("Raids").getAllKeys()){var row=raw.getCompound("Raids").getCompound(key);if(!row.getBoolean("Done")&&(retreat||now<row.getLong("Born")||now-row.getLong("Born")>=6000)){row.putBoolean("Done",true);setDirty();}}}
    void command(long now){if(problem.isEmpty()&&raw.getLong("NextGlobal")>now+200){raw.putLong("NextGlobal",now+200);setDirty();}}
    private boolean checkpoint(MinecraftServer server){try{var path=server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(generation)+".dat");if(Files.isSymbolicLink(path)||Files.isSymbolicLink(path.getParent()))throw new java.io.IOException("Ambiguous raid storage");setDirty();server.overworld().getDataStorage().save();var n=com.coraline.rebirth.StoryRunStore.read(path);if(!n.contains("data",Tag.TAG_COMPOUND)||!n.getCompound("data").equals(raw))throw new java.io.IOException("Raid checkpoint mismatch");return true;}catch(java.io.IOException|RuntimeException failed){problem="Raid admission checkpoint failed";return false;}}
    @Override public CompoundTag save(CompoundTag n){return n.merge(raw.copy());}
}
